def transform(g):
    g=[r[:] for r in g]; H,W=len(g),len(g[0])
    # find block color: most common nonzero
    from collections import Counter
    c=Counter(x for r in g for x in r if x)
    block=min(c,key=c.get)  # rectangle is big; dots are the rare color
    # actually block color = most frequent nonzero
    block=max(c,key=c.get); dot=min(c,key=c.get)
    rows=[i for i in range(H) if block in g[i]]
    cols=[j for j in range(W) if any(g[i][j]==block for i in rows)]
    r0,r1,c0,c1=min(rows),max(rows),min(cols),max(cols)
    # dots
    dots=[(i,j) for i in range(H) for j in range(W) if g[i][j]==dot]
    out=[r[:] for r in g]
    # horizontal: rows of block with no dot in that row -> fill entire row
    dotrows={i for i,j in dots}
    for i in range(r0,r1+1):
        if i not in dotrows:
            out[i]=[block]*W
    # vertical: block columns with no dot below block -> fill down to bottom
    below=[(i,j) for i,j in dots if i>r1]
    dotcols={j for i,j in below}
    for j in range(c0,c1+1):
        if j not in dotcols:
            for i in range(r1+1,H):
                out[i][j]=block
    return out

